@Configuration
public class NioTransportConfiguration {

    @Bean
    @ConditionalOnProperty(name = "server.transport.type", havingValue = "epoll", matchIfMissing = false)
    @ConditionalOnClass(name = "io.netty.channel.epoll.EpollChannelOption")
    public NetworkChannelManager epollChannelManager() {
        return new EpollSocketChannelManager();
    }

    @Bean
    @ConditionalOnMissingBean(NetworkChannelManager.class)
    public NetworkChannelManager defaultNioChannelManager() {
        return new StandardNioChannelManager();
    }
}
